import sys; S = sys.argv[1]
def patch(path, reps):
    s = open(path, encoding='utf-8').read()
    for a, b in reps:
        assert a in s, (path.split('/')[-1], a[:90]); s = s.replace(a, b)
    open(path, 'w', encoding='utf-8').write(s); print('patched', path.split('/')[-1], len(reps))
